insert into public.brands (id, profile_id, brand_name, brand_slug, brand_logo_url, brand_pronunciation, website_url, description, industry, location, contact_email, contact_phone)
values
  ('b1000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'Kumkum Naturals', 'kumkum-naturals', '/demo/brands/kumkum-naturals.svg', 'KUM-kum na-chu-RALS', 'https://www.kumkum-naturals.example', 'Ayurveda-inspired skincare made in small batches with cold-pressed oils and Rajasthani botanicals.', 'Beauty & personal care', 'Jaipur', 'kumkum@brands.example', '+91 98290 11223'),
  ('b1000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 'Urban Tiffin Co.', 'urban-tiffin-co', '/demo/brands/urban-tiffin-co.svg', 'UR-ban TIF-in co', 'https://www.urban-tiffin-co.example', 'Homestyle meal boxes delivered hot across Mumbai — dal, sabzi and love, packed daily.', 'Food & beverage', 'Mumbai', 'urbantiffin@brands.example', '+91 98200 44556'),
  ('b1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'Nimbus Audio', 'nimbus-audio', '/demo/brands/nimbus-audio.svg', 'NIM-bus AW-dee-oh', 'https://www.nimbus-audio.example', 'Wireless earbuds and speakers tuned for Indian music and long commutes.', 'Consumer electronics', 'Bengaluru', 'nimbus@brands.example', '+91 98450 77889'),
  ('b1000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000004', 'Saffron Street', 'saffron-street', '/demo/brands/saffron-street.svg', 'SAF-ron street', 'https://www.saffron-street.example', 'Contemporary ethnic wear for everyday — breathable cotton kurtas, co-ords and festive sets.', 'Fashion & apparel', 'Delhi', 'saffron@brands.example', '+91 98110 22334'),
  ('b1000000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000005', 'Peak Protein Labs', 'peak-protein-labs', '/demo/brands/peak-protein-labs.svg', 'peek PRO-teen labs', 'https://www.peak-protein-labs.example', 'Clean-label whey, plant protein and electrolytes — third-party tested, no fillers.', 'Health & fitness', 'Pune', 'peakprotein@brands.example', '+91 98220 55667'),
  ('b1000000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000006', 'Chai Circle', 'chai-circle', '/demo/brands/chai-circle.svg', 'chai SUR-kul', 'https://www.chai-circle.example', 'Single-estate Darjeeling and Assam chai blends with small-batch snacks.', 'Food & beverage', 'Kolkata', 'chaicircle@brands.example', '+91 98300 88990'),
  ('b1000000-0000-4000-8000-000000000007', 'a1000000-0000-4000-8000-000000000007', 'Loom & Lace', 'loom-and-lace', '/demo/brands/loom-and-lace.svg', 'loom and lace', 'https://www.loom-and-lace.example', 'Handloom sarees, stoles and dupattas woven with artisan clusters across Gujarat.', 'Fashion & apparel', 'Surat', 'loomlace@brands.example', '+91 98250 12121'),
  ('b1000000-0000-4000-8000-000000000008', 'a1000000-0000-4000-8000-000000000008', 'Byte Gadgets', 'byte-gadgets', '/demo/brands/byte-gadgets.svg', 'bite GAD-jets', 'https://www.byte-gadgets.example', 'Smart plugs, lights and home gadgets that just work with your phone.', 'Consumer electronics', 'Hyderabad', 'bytegadgets@brands.example', '+91 98490 34343'),
  ('b1000000-0000-4000-8000-000000000009', 'a1000000-0000-4000-8000-000000000009', 'Wander Bags', 'wander-bags', '/demo/brands/wander-bags.svg', 'WAN-der bags', 'https://www.wander-bags.example', 'Travel backpacks and organisers designed for Indian trains, flights and road trips.', 'Travel & hospitality', 'Goa', 'wanderbags@brands.example', '+91 98220 56565'),
  ('b1000000-0000-4000-8000-00000000000a', 'a1000000-0000-4000-8000-00000000000a', 'Little Sprouts', 'little-sprouts', '/demo/brands/little-sprouts.svg', 'LIT-ul sprouts', 'https://www.little-sprouts.example', 'Organic baby care, gentle bath products and wooden toys for little ones.', 'Parenting & kids', 'Chennai', 'littlesprouts@brands.example', '+91 98410 78787');
insert into public.creators (id, profile_id, display_name, slug, headline, bio, profile_image_url, cover_image_url, gender, age, city, state, country, creator_type, engagement_rate, verified, available, response_time, status, featured, onboarding_step, rejection_reason, published_at, approved_at)
values
  ('c1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'Aanya Kapoor', 'aanya-kapoor', 'Everyday makeup that survives Delhi summers', 'I make honest, no-filter makeup and skincare videos for real Indian skin. My audience trusts me for long-wear tests, dupes and routines that fit a busy morning. I love working with homegrown brands.', '/demo/avatars/creator-01.svg', '/demo/covers/beauty.svg', 'female', 26, 'Delhi', 'Delhi', 'India', 'micro_creator', 3.84, true, true, 'within_1_day', 'published', true, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-000000000002', 'a2000000-0000-4000-8000-000000000002', 'Rhea Menon', 'rhea-menon', 'Skincare that respects humid weather', 'Certified skincare nerd from Kochi. I break down ingredients, test textures on camera and build simple routines for humid climates. Expect calm, clean visuals and clear explanations.', '/demo/avatars/creator-02.svg', '/demo/covers/skincare.svg', 'female', 29, 'Kochi', 'Kerala', 'India', 'micro_creator', 6.25, false, true, 'within_1_day', 'published', false, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-000000000003', 'a2000000-0000-4000-8000-000000000003', 'Kabir Sethi', 'kabir-sethi', 'Gadgets explained in 60 seconds', 'I review phones, audio and smart-home tech with a focus on what actually matters for Indian buyers. Crisp unboxings, honest pros and cons, and studio-quality audio.', '/demo/avatars/creator-03.svg', '/demo/covers/technology.svg', 'male', 31, 'Mumbai', 'Maharashtra', 'India', 'influencer', 2.84, true, true, 'within_few_hours', 'published', true, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-000000000004', 'a2000000-0000-4000-8000-000000000004', 'Ishita Rao', 'ishita-rao', 'Outfit ideas you can actually wear to work', 'Bengaluru-based stylist and creator. I style everyday, sustainable and festive looks with easy transitions and flat lays. My community loves try-on hauls and capsule wardrobes.', '/demo/avatars/creator-04.svg', '/demo/covers/fashion.svg', 'female', 24, 'Bengaluru', 'Karnataka', 'India', 'micro_creator', 2.18, true, true, 'within_few_hours', 'published', true, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-000000000005', 'a2000000-0000-4000-8000-000000000005', 'Arjun Nair', 'arjun-nair', 'Home workouts and high-protein South Indian food', 'Strength coach turned creator. I share no-equipment workouts, meal-prep ideas and supplement reviews without the bro-science. Clean, energetic edits.', '/demo/avatars/creator-05.svg', '/demo/covers/fitness.svg', 'male', 27, 'Chennai', 'Tamil Nadu', 'India', 'micro_creator', 4.34, false, true, 'within_1_hour', 'published', false, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-000000000006', 'a2000000-0000-4000-8000-000000000006', 'Meher Gill', 'meher-gill', 'Punjabi wedding-season fashion on a budget', 'Small but mighty community of 9K who love wedding-guest looks, jutti styling and budget festive fits. Warm, high-engagement content.', '/demo/avatars/creator-06.svg', '/demo/covers/fashion.svg', 'female', 25, 'Chandigarh', 'Punjab', 'India', 'nano_creator', 1.81, false, true, 'within_few_hours', 'published', false, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-000000000007', 'a2000000-0000-4000-8000-000000000007', 'Dev & Tara', 'dev-and-tara', 'A couple who turns weekends into mini adventures', 'We’re Dev and Tara — road trips, cosy stays, gifting ideas and relatable couple moments. Our audience books what we recommend.', '/demo/avatars/creator-07.svg', '/demo/covers/couple.svg', 'prefer_not_to_say', 30, 'Pune', 'Maharashtra', 'India', 'influencer', 6.48, true, true, 'within_1_hour', 'published', true, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-000000000008', 'a2000000-0000-4000-8000-000000000008', 'Sana Qureshi', 'sana-qureshi', 'Hyderabadi recipes, done in under 20 minutes', 'Home cook sharing quick Hyderabadi and fusion recipes, kitchen hacks and honest taste tests. Warm narration and top-down cooking shots.', '/demo/avatars/creator-08.svg', '/demo/covers/food.svg', 'female', 30, 'Hyderabad', 'Telangana', 'India', 'micro_creator', 4.48, false, true, 'within_few_hours', 'published', false, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-000000000009', 'a2000000-0000-4000-8000-000000000009', 'Vikram Joshi', 'vikram-joshi', 'Personal finance in plain Gujarati and Hindi', 'Chartered accountant simplifying money — SIPs, tax-saving and budgeting for first-time earners. Trusted, compliance-aware explainers.', '/demo/avatars/creator-09.svg', '/demo/covers/finance.svg', 'male', 34, 'Ahmedabad', 'Gujarat', 'India', 'influencer', 5.34, true, false, 'within_few_hours', 'published', true, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-00000000000a', 'a2000000-0000-4000-8000-00000000000a', 'Nisha Pillai', 'nisha-pillai', 'Toddler-mom life without the perfect filter', 'Mom of a three-year-old sharing honest product reviews, routines and parenting hacks. My audience is young parents in metros.', '/demo/avatars/creator-10.svg', '/demo/covers/parenting.svg', 'female', 28, 'Mumbai', 'Maharashtra', 'India', 'micro_creator', 4.75, true, true, 'within_few_hours', 'published', false, 7, null, now(), now()),
  ('c1000000-0000-4000-8000-00000000000b', 'a2000000-0000-4000-8000-00000000000b', 'Rohan Das', 'rohan-das', 'Mobile gaming, setups and budget gear', 'Streamer and reviewer focused on mobile esports, controllers and budget setups. Fast-paced, meme-friendly edits.', '/demo/avatars/creator-11.svg', '/demo/covers/gaming.svg', 'male', 23, 'Kolkata', 'West Bengal', 'India', 'micro_creator', 1.60, false, true, 'within_1_day', 'published', false, 7, null, now(), now()),
